    counselor_desc: "ஆலோசகர்களைத் தேடுக, தபசில்கள் பார்க்கவும், ஆலோசகர் பிரிவிலிருந்து அரட்டை அல்லது சந்திப்பு ஆதரவை கோரவும்.",
