    profile_help: "சுயவிவரம்: உங்கள் பெயர், ஆபத்து, தொடர்பு விவரங்கள், பிறந்த தேதி, பாலினம், இரத்த வகை, முகவரி, அவசரம் தொடர்பு, மருத்துவ தகவல், காப்பீடு தகவல் மற்றும் இடம் புதுப்பிக்கவும்.",
