    security_help: "கணக்கு பாதுகாப்பு: கடவுச்சொல், உள்நுழைவு பாதுகாப்பு, மற்றும் இடம் அனுமதி கட்டுப்பாட்டுக்கு அமைப்புகளை பயன்படுத்தவும்.",
    emergency_help: "அவசర குறிப்பு: இந்த பயன்பாடு அவசரம் சেவையல்ல. தாமதமாக ஆபத்து அல்லது மருத்துவ அவசரத்திற்கு, உடனடியாக உள்ளூர் அவசர சேவைகளுடன் தொடர்பு கொள்ளவும்.",
    profile_not_updating: "சுயவிவரம் புதுப்பிக்கப்படவில்லை", profile_not_updating_desc: "தேவையான புலங்களை சரிபார்க்கவும், OTP ஐ மாற்றிய மின்னஞ்சல் அல்லது ஃபோன் சரிபார்க்கவும், பின்னர் மீண்டும் சேமிக்கவும்.",
    call_not_connecting: "அழைப்பு இணைக்கப்படவில்லை", call_not_connecting_desc: "கேமரா மற்றும் மைக்ரோஃபோன் அனுமதியை அனுமதிக்கவும், கோட்பாட்டாளர் திறந்திருக்கவும், உங்கள் இணைய இணைப்பை சரிபார்க்கவும்.",
