    payment_issue: "கட்டணம் சிக்கல்", payment_issue_desc: "பணப்பையைத் திறக்கவும் மற்றும் கட்டணம் விவரங்களுடன் ஆதரவைத் தொடர்புகொள்ளும் முன் சமீபத்திய செயல்பாட்டை மीளாய்வு செய்யவும்.",
    need_help: "கணக்கு உதவி தேவையா?", need_help_desc: "முதலில் உங்கள் சுயவிவரம் மற்றும் அமைப்புகளை சரிபார்க்கவும். தாமதமாக கவனிப்பு அல்லது அவசர சிக்கல்களுக்கு, உடனடியாக உள்ளூர் அவசர சேவைகளுடன் தொடர்பு கொள்ளவும்.",
    privacy_desc: "உங்கள் பயனர் கணக்கு, ஆரோக்கியம் சுயவிவரம், அரட்டை, சந்திப்புகள், அழைப்புகள், பாதுகாப்பு, மற்றும் அனுமதிகளுக்கான முக்கியமான தனியுரிமை புள்ளிகளை மீளாய்வு செய்யவும்.",
    privacy_highlights: "தனியுரிமை முக்கியத்துவ",
    otp_protected: "OTP பாதுகாப்பு", email_phone: "மின்னஞ்சல் மற்றும் ஃபோன்",
    manage_from: "இலிருந்து நிர்வகிக்கவும்", profile_settings: "சுயவிவரம் மற்றும் அமைப்புகள்",
    sensitive_areas: "உணர்வுশீல பகுதிகள்", health_chat_calls: "ஆரோக்கியம், அரட்டை, அழைப்புகள்",
    profile_data: "சுயவிவர ஈ", profile_data_desc: "பெயர், ஆபத்து, வயது, பாலினம், இரத்த வகை, தொடர்பு விவரங்கள், முகவரி, அவசரம் தொடர்பு, மருத்துவ தகவல், மற்றும் காப்பீடு தகவல் உங்கள் சுயவிவரம் காட்ட மற்றும் கவனிப்பு பணிப்பாய்வை ஆதரிக்க பயன்படுத்தப்படுகிறது.",
    chat_appointment_data: "அரட்டை மற்றும் சந்திப்பு ஈ", chat_appointment_data_desc: "AI அரட்டை, ஆலோசகர்요청, சந்திப்புகள், மற்றும் அழைப்பு வரலாறு பயன்பாடு உங்கள் ஆதரவு மற்றும் அமர்வு வரலாற்றை உங்கள் கணக்கிற்குள் கிடைக்க வைக்க உதவும்.",
    security_data: "பாதுகாப்பு ஈ", security_data_desc: "டோக்கன்கள், கடவுச்சொல் நிலை, OTP சரிபார்ப்பு, மற்றும் உள்நுழைவு விவரங்கள் கணக்கு பெறுநிலை மற்றும் உணர்வுசீல சுயவிவர மாற்றங்கள் பாதுகாக்க பயன்படுத்தப்படுகிறது.",
    location_data: "இடம் ஈ", location_data_desc: "இடம் சுயவிவர சூழ்நிலை, பொருத்தம், மற்றும் கையேடு புதுப்பிக்கல்களுக்கு கோரப்படுகிறது. நீங்கள் அமைப்புகள் அல்லது உங்கள் உலாவியிலிருந்து உலாவி இடம் அனுமதி நிர்வகிக்க முடியும்।",
    visible_to_you: "உங்களுக்குக் காணப்படும்", visible_to_you_desc: "உங்கள் சுயவிவரம், பணப்பை, சந்திப்பு பதிவுகள், அரட்டை வரலாறு, அமைப்புகள், மற்றும் பயனர் கோட்பாட்டாளரில் அழைப்பு வரலாறு.",
    shared_for_care: "கவனிப்புக்கு பகிரப்பட்ட", shared_for_care_desc: "பொருத்தமான சுயவிவரம்,요청, சந்திப்பு, மற்றும் அமர்வு விவரங்கள் உங்கள் ஆதரவில் சம்பந்தப்பட்ட ஆலோசகர்க்கு கிடைக்கும் இருக்கலாம்.",
    protected_changes: "பாதுகாப்பு மாற்றங்கள்", protected_changes_desc: "மின்னஞ்சல் மற்றும் ஃபோன் புதுப்பிக்கல்கள் உங்கள் சுயவிவரத்தில் செயலில் இருக்கும் முன் OTP சரிபார்ப்பு தேவை.",
    privacy_checklist: "முக்கியமான தனியுரிமை சரிபார்ப்பு",
    privacy_checklist_1: "OTP சரிபார்ப்பு மற்றும் கணக்கு மீட்பு சரியாக இயங்குவதற்கு உங்கள் ஃபோன் மற்றும் மின்னஞ்சல் அப்டுடேட் வைக்கவும்.",
    privacy_checklist_2: "மருத்துவ, ஒவ்வாமை, மருந்து, மற்றும் அவசরம் தொடர்பு விவரங்கள் சரியான தகவல் மட்டுமே புதுப்பிக்கவும்.",
    privacy_checklist_3: "பகிரப்பட்ட சாதனங்களில் வெளியேறும் பயன்படுத்தவும் பின்வருவனவற்றை அடுத்த நபர் உங்கள் கோட்பாட்டாளர் மூடிவிடக்க முடியாது.",
    privacy_checklist_4: "அழைப்புகள் அல்லது இடம் புதுப்பிக்கல்கள் வேலை செய்யாது என்றால் உலாவி கேமரா, மைக்रோஃபோன், மற்றும் இடம் அனுமதி மீளாய்வு செய்யவும்.",
    privacy_checklist_5: "அரட்டை அல்லது சந்திப்புகளில் நீங்கள் கவனிப்பு ஆதரவிற்கு உபயோகிக்கக் கூடிய தகவல் மட்டுமே பகிரவும்।",
    privacy_checklist_6: "கணக்கு கட்டியெறியுங்கள் கவனிப்பு கண்டுபிடிக்கவும் கணக்கு நீக்கம் சுயவிவரம், சந்திப்பு, அரட்டை, பணப்பை, மற்றும் அமர்வு வரலாறு தாக்கமுறக்கூடும்.",
