    profile_not_updating: "ప్రొఫైల్ అప్‌డేట్ చేయడం లేదు", profile_not_updating_desc: "తప్పనిసరి ఫీల్డ్‌లను తనిఖీ చేసి, OTP ద్వారా మార్పు చేసిన ఇమెయిల్ లేదా ఫోన్‌ను ధృవీకరించి, ఆపై మళ్లీ సేవ్ చేయండి.",
