    payment_issue: "చెల్లింపు సమస్య", payment_issue_desc: "వాలెట్‌ను తెరిచి, చెల్లింపు వివరాలతో సపోర్టుకు సంప్రదించే ముందు ఇటీవలి కార్యకలాపాన్ని సమీక్షించండి.",
    need_help: "ఖాతా సహాయం అవసరమైనా?", need_help_desc: "ముందుగా మీ ప్రొఫైల్ మరియు సెట్టింగ్‌లను చెక్ చేయండి. తక్షణ సంరక్షణ లేదా ఎమర్జెన్సీ సమస్యల కోసం, వెంటనే స్థానిక ఎమర్జెన్సీ సేవలను సంప్రదించండి.",
    privacy_desc: "మీ వినియోగదారు ఖాతా, ఆరోగ్య ప్రొఫైల్, చాట్, అపాయింట్‌మెంట్లు, కాల్‌లు, భద్రత మరియు అనుమతుల కోసం ముఖ్యమైన గోప్యత పాయింట్‌లను సమీక్షించండి.",
