    sensitive_areas: "సూక్ష్మమైన ప్రాంతాలు", health_chat_calls: "ఆరోగ్యం, చాట్, కాల్‌లు",
    profile_data: "ప్రొఫైల్ డేటా", profile_data_desc: "పేరు, ఫోటో, వయస్సు, లింగం, రక్త సమూహం, సంపర్క వివరాలు, చిరునామా, ఎమర్జెన్సీ సంపర్కం, చిక్త్స సమాచారం మరియు బీమా సమాచారం మీ ప్రొఫైల్‌ను చూపించడానికి మరియు సంరక్షణ పని ప్రవాహాలకు సహాయం చేయడానికి ఉపయోగించబడుతుంది.",
    chat_appointment_data: "చాట్ మరియు అపాయింట్‌మెంట్ డేటా", chat_appointment_data_desc: "AI చాట్, కౌన్సెలర్ అభ్యర్థనలు, అపాయింట్‌మెంట్‌లు మరియు కాల్ చరిత్ర, మీ ఖాతలో ఆपntar సపోర్ట్ మరియు సెషన్ చరిత్రను ఇంటిలో ఉంచడానికి సహాయపడతాయి.",
    security_data: "భద్రత డేటా", security_data_desc: "టోకన్‌లు, పాస్‌వర్డ్ స్థితి, OTP ధృవీకరణ మరియు లాగిన్ వివరాలు ఖాతా యాక్సెస్ మరియు సూక్ష్మమైన ప్రొఫైల్ మార్పులను రక్షించడానికి ఉపయోగించబడుతుంది.",
    location_data: "స్థానం డేటా", location_data_desc: "ప్రొఫైల్ సందర్భం, సరిపోతుంది మరియు మానవ అప్‌డేట్‌ల కోసం స్థానం అభ్యర్థించబడుతుంది. మీరు సెట్టింగ్‌ల నుండి లేదా మీ విహారిణి నుండి బ్రౌజర్ స్థానం అనుమతిని నిర్వహించవచ్చు.",
