    shared_for_care: "సంరక్షణ కోసం భాగస్వామ్యం చేయబడింది", shared_for_care_desc: "సంబంధితమైన ప్రొఫైల్, అభ్యర్థన, అపాయింట్‌మెంట్ మరియు సెషన్ వివరాలు మీ సపోర్టులో ఉన్న కౌన్సెలర్‌కు అందుబాటులో ఉండవచ్చు.",
    protected_changes: "సంరక్షిత మార్పులు", protected_changes_desc: "ఇమెయిల్ మరియు ఫోన్ అప్‌డేట్‌లు మీ ప్రొఫైల్‌లో సక్రియమయ్యే ముందు OTP ధృవీకరణ అవసరమవుతుంది.",
