    privacy_checklist_2: "చిక్త్స, అలెర్జీ, మందు మరియు ఎమర్జెన్సీ సంపర్క వివరాలను ఖచ్చితమైన సమాచారం ద్వారా మాత్రమే అప్‌డేట్ చేయండి.",
    privacy_checklist_3: "భాగస్వామ్య పరికరాలపై లాగ్‌అవుట్‌ను ఉపయోగించండి, తద్వారా తదుపరి వ్యక్తి మీ డ్యాష్‌బోర్డ్‌ను తెరవలేరు.",
