    security_data: "സുരക്ഷ ഡാറ്റാ", security_data_desc: "ടോകന്നുകൾ, പാസ്‌വേഡ് സ്ഥിതി, OTP സത്യാപനം, ലോഗിൻ വിവരങ്ങൾ ഖാത്ത ആക്സസ്, സംവേദനശീല പ്രൊഫൈൽ പരിവർത്തനങ്ങൾ സംരക്ഷിക്കാൻ ഉപയോഗിക്കുന്നത്.",
