    security_data: "સુરક્ષા ડેટા", security_data_desc: "ટોકન્સ, પાસવર્ડ સ્થિતિ, OTP ચકાસણી અને લૉગિન તથ્યો ખાતા પ્રવેશ અને સંવેદનશીલ પ્રોફાઇલ બદલાવોને સુરક્ષિત કરવા માટે ઉપયોગ કરવામાં આવે છે.",
    location_data: "સ્થાન ડેટા", location_data_desc: "પ્રોફાઇલ સંદર્ભ, મેળવણી અને મેનુવલ અપડેટ્સ માટે સ્થાન માંગવામાં આવે છે. તમે સેટિંગ્સ અથવા તમારા બ્રાઉજર માંથી બ્રાઉજર સ્થાન અનુમતિ સંચાલિત કરી શકો છો.",
    visible_to_you: "તમને દૃશ્યમાન", visible_to_you_desc: "તમારી પ્રોફાઇલ, વૉલેટ, એપોઇન્ટમેન્ટ રેકોર્ડ્સ, ચેટ ઇતિહાસ, સેટિંગ્સ અને વપરાશકર્તા ડેશબોર્ડમાં કોલ ઇતિહાસ.",
    shared_for_care: "સંભાળ માટે શેર કર્યું", shared_for_care_desc: "સંબંધિત પ્રોફાઇલ, વિનંતિ, એપોઇન્ટમેન્ટ અને સેશન તથ્યો તમારી સહાયમાં જોડાયેલા કાઉન્સેલરને ઉપલબ્ધ હોઈ શકે છે.",
    protected_changes: "સુરક્ષિત બદલાવો", protected_changes_desc: "ઈમેલ અને ફોન અપડેટ્સ તમારી પ્રોફાઇલમાં સક્રિય થવા પહેલાં OTP ચકાસણીની જરૂર હોય છે.",
    privacy_checklist: "મહત્વપૂર્ણ ગોપનીયતા ચેકલિસ્ટ",
